CREATE TABLE IF NOT EXISTS collaboration_events(id bigserial PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,actor_id uuid NOT NULL REFERENCES users(id),event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS collaboration_events_project_idx ON collaboration_events(project_id,id);
CREATE TABLE IF NOT EXISTS releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,revision_id uuid NOT NULL REFERENCES revisions(id),version text NOT NULL,channel text NOT NULL DEFAULT 'development',artifact_uri text,artifact_sha256 text,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','withdrawn')),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version));
